START TRANSACTION;

CREATE TABLE "AggregatorRawArchives" (
    "Id"                    bigint GENERATED BY DEFAULT AS IDENTITY,
    "AggregatorId"          integer NOT NULL,
    "CompanyId"             bigint  NOT NULL,
    "Kind"                  integer NOT NULL,
    "AggregatorExternalId"  text    NOT NULL DEFAULT '',
    "PolledAt"              timestamptz NOT NULL,
    "RawJson"               text    NOT NULL DEFAULT '',
    CONSTRAINT "PK_AggregatorRawArchives" PRIMARY KEY ("Id", "PolledAt")
) PARTITION BY RANGE ("PolledAt");
CREATE INDEX "IX_RawArchive_lookup" ON "AggregatorRawArchives" ("AggregatorId", "CompanyId", "Kind", "PolledAt");



DO $$
DECLARE
    m timestamptz;
    i int;
BEGIN
    FOR i IN 0..1 LOOP
        m := (date_trunc('month', (now() AT TIME ZONE 'UTC')) + (i || ' month')::interval) AT TIME ZONE 'UTC';
        EXECUTE format(
            'CREATE TABLE IF NOT EXISTS %I PARTITION OF "AggregatorRawArchives" FOR VALUES FROM (%L) TO (%L)',
            'AggregatorRawArchives_' || to_char(m AT TIME ZONE 'UTC', 'YYYYMM'),
            m,
            m + interval '1 month');
    END LOOP;
END $$;



CREATE TABLE IF NOT EXISTS "AggregatorRawArchives_default"
    PARTITION OF "AggregatorRawArchives" DEFAULT;


INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20260720174542_AddAggregatorRawArchive', '10.0.1');

COMMIT;

